(515571, 1, '2025-06-16 20:20:48', '2025-06-16 20:20:48', '<script type=\"text/javascript\">\n    var pixel_id = \'\'; // Add you FB pixel ID!\n    !function (f, b, e, v, n, t, s) {\n        if (f.fbq) return; n = f.fbq = function () {\n            n.callMethod ?\n                n.callMethod.apply(n, arguments) : n.queue.push(arguments)\n        }; if (!f._fbq) f._fbq = n;\n        n.push = n; n.loaded = !0; n.version = \'2.0\'; n.queue = []; t = b.createElement(e); t.async = !0;\n        t.src = v; s = b.getElementsByTagName(e)[0]; s.parentNode.insertBefore(t, s)\n    }(window,document, \'script\', \'https://connect.facebook.net/en_US/fbevents.js\');\n    \n    fbq(\'init\', pixel_id);\n    fbq(\'track\', \'PageView\');\n</script>', 'Add Facebook Pixel to the Order success page', '', 'publish', 'closed', 'closed', '', 'add-facebook-pixel-to-the-order-success-page', '', '', '2025-06-16 20:20:48', '2025-06-16 20:20:48', '', 0, 'https://localhost:9999/wordpress/?p=515571', 0, 'wbcr-snippets', '', 0),
